-- Prepared operator harness; no DDL, network, worker, or external file reads.
-- Run only after reviewing/installing migration.sql. ALL fixture table writes rollback.
-- Identity sequence gaps are normal PostgreSQL nontransactional effects; no records persist.
DO $tests$
DECLARE
 results jsonb:='[]'; releasehash text; manifest text:=repeat('c',64); commitid text:=repeat('e',40);
 synthetic_token text:=repeat('a',64); cap text:=repeat('b',64); badcap text:=repeat('f',64);
 corehash text:=sol_action.runtime_hash(); bridgehash text:=sol_action_bridge.runtime_hash(); guardhash text:=sol_creation_guard.runtime_hash();
 successful_job uuid:=gen_random_uuid(); successful_req uuid:=gen_random_uuid(); refused_job uuid:=gen_random_uuid(); refused_req uuid:=gen_random_uuid();
 pending_job uuid:=gen_random_uuid(); pending_req uuid:=gen_random_uuid(); legacy_job uuid:=gen_random_uuid(); legacy_req uuid:=gen_random_uuid();
 qid uuid; jid uuid; rid uuid; ph text; bh text; capraw bytea; n integer; before_n bigint; after_n bigint;
 d jsonb; envelope jsonb; good jsonb; refusal jsonb; r jsonb; prior jsonb; foreign_read jsonb; absent_read jsonb; pending_read jsonb;
 initial_guard bigint:=(SELECT count(*) FROM sol_creation_guard.requests);
 initial_events bigint:=(SELECT count(*) FROM sol_creation_guard.events);
 initial_jobs bigint:=(SELECT count(*) FROM sol_action.jobs);
 initial_intents bigint:=(SELECT count(*) FROM sol_action.intents);
 initial_outcomes bigint:=(SELECT count(*) FROM sol_action.outcomes);
 initial_releases bigint:=(SELECT count(*) FROM sol_action_bridge.releases);
 initial_admissions bigint:=(SELECT count(*) FROM sol_creation_guard.admissions);
 utcday timestamptz:=date_trunc('day',clock_timestamp() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC';
BEGIN
 BEGIN
  releasehash:=sol_creation_guard.sha(manifest||':'||commitid);
  IF EXISTS(SELECT 1 FROM sol_action_bridge.releases x WHERE x.release_hash=releasehash)
     OR (SELECT count(*) FROM sol_action.jobs x WHERE x.created_at>=utcday)>=126
     OR (SELECT count(*) FROM sol_creation_guard.requests x WHERE x.reserved_at>=utcday)>=124 THEN
   RAISE EXCEPTION 'SYNTHETIC_FIXTURE_COLLISION_OR_CAPACITY_REQUIRES_REVIEW';
  END IF;
  INSERT INTO sol_action_bridge.releases(release_hash,manifest_hash,source_commit,source_files,deployment_id,deployment_url,token_sha256)
  VALUES(releasehash,manifest,commitid,jsonb_build_object('api/job.py',repeat('d',64),'bridge_runtime.py',repeat('8',64)),
   'SYNTHETIC_GUARD_ROLLBACK_TEST','https://synthetic-guard-test.vercel.app',sol_creation_guard.sha(synthetic_token));
  INSERT INTO sol_creation_guard.admissions(release_hash) VALUES(releasehash);
  d:=jsonb_build_object('job_id',successful_job,'request_id',successful_req,'capability',cap,
    'mandate','SYNTHETIC: sum exact cents; never a general mandate proof',
    'requirements',jsonb_build_array('Conserve this exact synthetic requirement'),
    'source_csv',E'id,currency,amount\na,EUR,1.00\n','source_origin',jsonb_build_object('kind','declared'));
  envelope:=jsonb_build_object('core_input',d,'release_hash',releasehash,'manifest_hash',manifest,'source_commit',commitid,'self_hash',repeat('d',64),'bridge_token',synthetic_token);

 before_n:=(SELECT count(*) FROM sol_creation_guard.requests);
 r:=public.sol_action_creation_api('create_guarded',envelope||jsonb_build_object('client_verdict','PASS'));
 results:=results||jsonb_build_array(jsonb_build_object('name','malformed_envelope_no_reservation','pass',coalesce((r->>'error'='NOT_AUTHORIZED_OR_INVALID_REFERENCE' AND (SELECT count(*) FROM sol_creation_guard.requests)=before_n),false)));
 r:=public.sol_action_creation_api('create_guarded',jsonb_set(envelope,'{bridge_token}',to_jsonb(badcap)));
 results:=results||jsonb_build_array(jsonb_build_object('name','wrong_release_token_no_reservation','pass',coalesce((r->>'error'='NOT_AUTHORIZED_OR_INVALID_REFERENCE' AND (SELECT count(*) FROM sol_creation_guard.requests)=before_n),false)));
 r:=public.sol_action_creation_api('create_guarded',jsonb_set(envelope,'{core_input,requirements}','[]'::jsonb));
 results:=results||jsonb_build_array(jsonb_build_object('name','malformed_requirements_no_reservation','pass',coalesce((r->>'error'='NOT_AUTHORIZED_OR_INVALID_REFERENCE' AND (SELECT count(*) FROM sol_creation_guard.requests)=before_n),false)));
 good:=public.sol_action_creation_api('create_guarded',envelope);
 results:=results||jsonb_build_array(jsonb_build_object('name','real_core_creation_once','pass',coalesce((good->'ok'='true'::jsonb AND good->>'action'='create' AND good->>'status'='RECORDED' AND good->>'job_id'=successful_job::text AND good->>'request_id'=successful_req::text AND (SELECT count(*) FROM sol_action.jobs x WHERE x.job_id=successful_job)=1 AND (SELECT count(*) FROM sol_action.intents x WHERE x.job_id=successful_job)=1),false)));
 before_n:=(SELECT count(*) FROM sol_creation_guard.events); r:=public.sol_action_creation_api('lookup_receipt',jsonb_build_object('job_id',successful_job,'capability',cap,'target_request_id',successful_req));
 results:=results||jsonb_build_array(jsonb_build_object('name','successful_receipt_historical_read_only','pass',coalesce((r->'found'='true'::jsonb AND r->>'target_action'='create' AND r->>'receipt_kind'='CORE_CREATION_OUTCOME' AND r->>'status'='HISTORICAL_NOT_CURRENT' AND r->'receipt'->'current_reuse_authorized'='false'::jsonb AND r->'receipt'->'needs_current_revalidation'='true'::jsonb AND NOT(r->'receipt' ? 'source_csv') AND (SELECT count(*) FROM sol_creation_guard.events)=before_n),false)));
 r:=public.sol_action_creation_api('create_guarded',envelope);
 results:=results||jsonb_build_array(jsonb_build_object('name','success_exact_retry_historical_no_reexecution','pass',coalesce((r->>'status'='HISTORICAL_NOT_CURRENT' AND r->'deduplicated'='true'::jsonb AND (SELECT count(*) FROM sol_action.intents x WHERE x.job_id=successful_job)=1 AND (SELECT count(*) FROM sol_creation_guard.events)=before_n),false)));
 envelope:=jsonb_set(envelope,'{core_input,job_id}',to_jsonb(refused_job::text)); envelope:=jsonb_set(envelope,'{core_input,request_id}',to_jsonb(refused_req::text)); envelope:=jsonb_set(envelope,'{core_input,source_csv}',to_jsonb(E'wrong,currency,amount\na,EUR,1.00\n'::text)); refusal:=public.sol_action_creation_api('create_guarded',envelope);
 results:=results||jsonb_build_array(jsonb_build_object('name','sql_refusal_durable_without_job','pass',coalesce((refusal->'ok'='false'::jsonb AND refusal->>'error'='CSV_HEADER' AND refusal->>'receipt_kind'='CONTROLLED_CREATION_REFUSAL' AND refusal->'durable_refusal'='true'::jsonb AND refusal->'terminal'='true'::jsonb AND NOT EXISTS(SELECT 1 FROM sol_action.jobs x WHERE x.job_id=refused_job) AND NOT EXISTS(SELECT 1 FROM sol_action.intents x WHERE x.request_id=refused_req) AND NOT EXISTS(SELECT 1 FROM sol_action.outcomes x WHERE x.request_id=refused_req)),false)));
 results:=results||jsonb_build_array(jsonb_build_object('name','controlled_scope_exact_not_composite','pass',coalesce((refusal->>'effect_scope'='CONTROLLED_CORE_DISPATCH_SUBTRANSACTION_ONLY' AND refusal->>'core_effect_scope'='THIS_RPC_SQL_TRANSACTION_ONLY' AND refusal->>'receipt_recording_effect'='APPEND_ONLY_CREATION_GUARD_RECEIPT_RECORDED' AND refusal->>'business_effect'='NONE_CORE_ACTION_ROLLED_BACK' AND refusal->'capability_activated_by_this_call'='false'::jsonb AND refusal->'automatic_retry'='false'::jsonb AND refusal->'current_reuse_authorized'='false'::jsonb),false)));
 before_n:=(SELECT count(*) FROM sol_creation_guard.events); r:=public.sol_action_creation_api('lookup_receipt',jsonb_build_object('job_id',refused_job,'capability',cap,'target_request_id',refused_req));
 results:=results||jsonb_build_array(jsonb_build_object('name','no_job_exact_receipt_historical_original_uuid','pass',coalesce((r->'found'='true'::jsonb AND r->>'status'='HISTORICAL_NOT_CURRENT' AND r->>'receipt_status'='REJECTED' AND r->>'target_action'='create' AND r->'receipt'->>'request_id'=refused_req::text AND (r->'receipt')-'status'-'current_reuse_authorized'-'needs_current_revalidation'-'begin_granted'-'binding_granted'-'historical_status'-'automatic_retry'=refusal-'status'-'current_reuse_authorized'-'needs_current_revalidation'-'begin_granted'-'binding_granted'-'historical_status'-'automatic_retry' AND (SELECT count(*) FROM sol_creation_guard.events)=before_n),false)));
 r:=public.sol_action_creation_api('create_guarded',envelope);
 results:=results||jsonb_build_array(jsonb_build_object('name','refusal_exact_retry_no_dispatch','pass',coalesce((r->'deduplicated'='true'::jsonb AND r->>'status'='HISTORICAL_NOT_CURRENT' AND (SELECT count(*) FROM sol_creation_guard.events)=before_n AND NOT EXISTS(SELECT 1 FROM sol_action.jobs x WHERE x.job_id=refused_job)),false)));
 r:=public.sol_action_creation_api('create_guarded',jsonb_set(envelope,'{core_input,mandate}',to_jsonb('changed'::text)));
 results:=results||jsonb_build_array(jsonb_build_object('name','same_uuid_changed_payload_rejected','pass',coalesce((r->>'error'='NOT_AUTHORIZED_OR_INVALID_REFERENCE' AND NOT(r ? 'effect_scope') AND (SELECT count(*) FROM sol_creation_guard.events)=before_n),false)));
 r:=public.sol_action_creation_api('create_guarded',jsonb_set(envelope,'{core_input,request_id}',to_jsonb(gen_random_uuid()::text)));
 results:=results||jsonb_build_array(jsonb_build_object('name','new_uuid_cannot_bypass_refused_job_intent','pass',coalesce((r->>'status'='OUTCOME_UNKNOWN' AND r->>'original_request_id'=refused_req::text AND r->'pending'='true'::jsonb AND (SELECT count(*) FROM sol_creation_guard.events)=before_n),false)));
 prior:=public.sol_action_creation_api('lookup_receipt',jsonb_build_object('job_id',refused_job,'capability',badcap,'target_request_id',refused_req)); foreign_read:=public.sol_action_creation_api('lookup_receipt',jsonb_build_object('job_id',gen_random_uuid(),'capability',cap,'target_request_id',refused_req)); absent_read:=public.sol_action_creation_api('lookup_receipt',jsonb_build_object('job_id',gen_random_uuid(),'capability',cap,'target_request_id',gen_random_uuid()));
 results:=results||jsonb_build_array(jsonb_build_object('name','wrongcap_crossjob_absent_uniform_opaque','pass',coalesce((prior=foreign_read AND foreign_read=absent_read AND prior->>'error'='NOT_AUTHORIZED_OR_INVALID_REFERENCE' AND NOT(prior ? 'found') AND NOT(prior ? 'effect_scope') AND NOT(prior ? 'job_id')),false)));
 r:=public.sol_action_creation_api('lookup_receipt',jsonb_build_object('job_id',gen_random_uuid(),'capability',cap,'target_request_id',successful_req));
 results:=results||jsonb_build_array(jsonb_build_object('name','foreign_legacy_uuid_cannot_be_probed_no_job','pass',coalesce((r=absent_read),false)));
 ph:=sol_creation_guard.sha('synthetic pending payload'); capraw:=extensions.digest(convert_to(cap,'UTF8'),'sha256'); bh:=sol_creation_guard.sha(encode(capraw,'hex')||':'||ph||':'||pending_job::text||':'||pending_req::text||':create');
 INSERT INTO sol_creation_guard.requests(request_id,job_id,payload_hash,capability_hash,request_binding_hash,release_hash,guard_runtime_hash,core_runtime_hash,bridge_runtime_hash) VALUES(pending_req,pending_job,ph,capraw,bh,releasehash,guardhash,corehash,bridgehash); PERFORM sol_creation_guard.append_event(pending_job,pending_req,'reservation',jsonb_build_object('payload_hash',ph,'request_binding_hash',bh));
 pending_read:=public.sol_action_creation_api('lookup_receipt',jsonb_build_object('job_id',pending_job,'capability',cap,'target_request_id',pending_req));
 results:=results||jsonb_build_array(jsonb_build_object('name','pending_intent_remains_unknown_not_no_effect','pass',coalesce((pending_read->'found'='false'::jsonb AND pending_read->>'status'='UNKNOWN' AND pending_read->'intent_found'='true'::jsonb AND pending_read->'receipt'='null'::jsonb AND pending_read->'automatic_retry'='false'::jsonb AND NOT(pending_read ? 'effect_scope')),false)));
 r:=public.sol_action_creation_api('create_guarded',jsonb_set(jsonb_set(envelope,'{core_input,job_id}',to_jsonb(pending_job::text)),'{core_input,request_id}',to_jsonb(gen_random_uuid()::text)));
 results:=results||jsonb_build_array(jsonb_build_object('name','pending_intent_new_uuid_blocked','pass',coalesce((r->>'status'='OUTCOME_UNKNOWN' AND r->>'original_request_id'=pending_req::text AND NOT EXISTS(SELECT 1 FROM sol_action.jobs x WHERE x.job_id=pending_job)),false)));
 d:=jsonb_set(jsonb_set(jsonb_set(d,'{job_id}',to_jsonb(legacy_job::text)),'{request_id}',to_jsonb(legacy_req::text)),'{source_csv}',to_jsonb(E'id,currency,amount\nx,USD,2.00\n'::text)); r:=sol_action.dispatch('create',d);
 results:=results||jsonb_build_array(jsonb_build_object('name','legacy_fixture_created_unmodified_core','pass',coalesce((r->'ok'='true'::jsonb AND NOT EXISTS(SELECT 1 FROM sol_creation_guard.requests x WHERE x.job_id=legacy_job)),false)));
 r:=public.sol_action_creation_api('lookup_receipt',jsonb_build_object('job_id',legacy_job,'capability',cap,'target_request_id',legacy_req));
 results:=results||jsonb_build_array(jsonb_build_object('name','legacy_success_recovered_only_with_authorized_job','pass',coalesce((r->'found'='true'::jsonb AND r->>'receipt_kind'='CORE_CREATION_OUTCOME' AND r->'receipt'->>'request_id'=legacy_req::text AND r->'receipt'->'current_reuse_authorized'='false'::jsonb),false)));
 BEGIN DELETE FROM sol_creation_guard.refusals WHERE request_id=refused_req; r:='false'; EXCEPTION WHEN insufficient_privilege THEN r:='true'; END;
 results:=results||jsonb_build_array(jsonb_build_object('name','delete_trigger_blocks_even_operator','pass',coalesce((r='true'::jsonb),false)));
 BEGIN UPDATE sol_creation_guard.requests SET payload_hash=repeat('0',64) WHERE request_id=refused_req; r:='false'; EXCEPTION WHEN insufficient_privilege THEN r:='true'; END;
 results:=results||jsonb_build_array(jsonb_build_object('name','update_trigger_blocks_even_operator','pass',coalesce((r='true'::jsonb),false)));
 BEGIN TRUNCATE sol_creation_guard.events; r:='false'; EXCEPTION WHEN insufficient_privilege THEN r:='true'; END;
 results:=results||jsonb_build_array(jsonb_build_object('name','truncate_trigger_blocks_even_operator','pass',coalesce((r='true'::jsonb),false)));
 results:=results||jsonb_build_array(jsonb_build_object('name','rls_and_client_table_acl_denied','pass',coalesce(((SELECT bool_and(c.relrowsecurity AND NOT has_table_privilege('anon',c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE') AND NOT has_table_privilege('authenticated',c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE')) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='sol_creation_guard' AND c.relkind='r')),false)));
 results:=results||jsonb_build_array(jsonb_build_object('name','public_wrapper_invoker_private_api_definer','pass',coalesce(((SELECT NOT p.prosecdef AND p.proconfig=ARRAY['search_path=""'] FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname='sol_action_creation_api') AND (SELECT p.prosecdef AND p.proconfig=ARRAY['search_path=""'] FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='sol_creation_guard' AND p.proname='api')),false)));
 results:=results||jsonb_build_array(jsonb_build_object('name','private_helpers_not_client_executable','pass',coalesce((NOT has_function_privilege('anon','sol_creation_guard.lookup(uuid,uuid,text)','EXECUTE') AND NOT has_function_privilege('authenticated','sol_creation_guard.create_guarded(jsonb)','EXECUTE') AND has_function_privilege('anon','public.sol_action_creation_api(text,jsonb)','EXECUTE')),false)));
 results:=results||jsonb_build_array(jsonb_build_object('name','registry_chain_before_quota_fixtures_valid','pass',coalesce((sol_creation_guard.audit()->'valid'='true'::jsonb),false)));
 FOR n IN 1..greatest(0,32-(SELECT count(*)::integer FROM sol_creation_guard.requests x WHERE x.reserved_at>=utcday AND x.capability_hash=capraw)) LOOP jid:=gen_random_uuid(); rid:=gen_random_uuid(); ph:=sol_creation_guard.sha('quota cap fixture '||n); bh:=sol_creation_guard.sha(encode(capraw,'hex')||':'||ph||':'||jid::text||':'||rid::text||':create'); INSERT INTO sol_creation_guard.requests(request_id,job_id,payload_hash,capability_hash,request_binding_hash,release_hash,guard_runtime_hash,core_runtime_hash,bridge_runtime_hash) VALUES(rid,jid,ph,capraw,bh,releasehash,guardhash,corehash,bridgehash); PERFORM sol_creation_guard.append_event(jid,rid,'reservation',jsonb_build_object('payload_hash',ph,'request_binding_hash',bh)); END LOOP;
 before_n:=(SELECT count(*) FROM sol_creation_guard.requests); r:=public.sol_action_creation_api('create_guarded',jsonb_set(jsonb_set(envelope,'{core_input,job_id}',to_jsonb(gen_random_uuid()::text)),'{core_input,request_id}',to_jsonb(gen_random_uuid()::text)));
 results:=results||jsonb_build_array(jsonb_build_object('name','per_cap_quota32_no_reservation_no_false_receipt','pass',coalesce((r->>'error'='CREATION_ADMISSION_LIMIT' AND r->'admission_recorded'='false'::jsonb AND NOT(r ? 'durable_refusal') AND NOT(r ? 'effect_scope') AND (SELECT count(*) FROM sol_creation_guard.requests)=before_n),false)));
 FOR n IN 1..greatest(0,128-(SELECT count(*)::integer FROM sol_creation_guard.requests x WHERE x.reserved_at>=utcday)) LOOP jid:=gen_random_uuid(); rid:=gen_random_uuid(); ph:=sol_creation_guard.sha('quota global fixture '||n); bh:=sol_creation_guard.sha(encode(capraw,'hex')||':'||ph||':'||jid::text||':'||rid::text||':create'); INSERT INTO sol_creation_guard.requests(request_id,job_id,payload_hash,capability_hash,request_binding_hash,release_hash,guard_runtime_hash,core_runtime_hash,bridge_runtime_hash) VALUES(rid,jid,ph,capraw,bh,releasehash,guardhash,corehash,bridgehash); PERFORM sol_creation_guard.append_event(jid,rid,'reservation',jsonb_build_object('payload_hash',ph,'request_binding_hash',bh)); END LOOP;
 before_n:=(SELECT count(*) FROM sol_creation_guard.requests); r:=public.sol_action_creation_api('create_guarded',jsonb_set(jsonb_set(jsonb_set(envelope,'{core_input,job_id}',to_jsonb(gen_random_uuid()::text)),'{core_input,request_id}',to_jsonb(gen_random_uuid()::text)),'{core_input,capability}',to_jsonb(badcap)));
 results:=results||jsonb_build_array(jsonb_build_object('name','global_quota128_no_reservation','pass',coalesce((r->>'error'='CREATION_ADMISSION_LIMIT' AND r->'admission_recorded'='false'::jsonb AND (SELECT count(*) FROM sol_creation_guard.requests)=before_n),false)));
 results:=results||jsonb_build_array(jsonb_build_object('name','registry_chain_after_quota_fixtures_valid','pass',coalesce((sol_creation_guard.audit()->'valid'='true'::jsonb),false)));
 RAISE EXCEPTION USING ERRCODE='PZ001',MESSAGE='SYNTHETIC_FIXTURE_ROLLBACK';
 EXCEPTION WHEN SQLSTATE 'PZ001' THEN NULL; WHEN OTHERS THEN results:=results||jsonb_build_array(jsonb_build_object('name','harness_unexpected_error','pass',false,'sqlstate',SQLSTATE,'error',left(SQLERRM,300))); END;
 results:=results||jsonb_build_array(jsonb_build_object('name','all_fixture_records_rolled_back','pass',coalesce(((SELECT count(*) FROM sol_creation_guard.requests)=initial_guard AND (SELECT count(*) FROM sol_creation_guard.events)=initial_events AND (SELECT count(*) FROM sol_action.jobs)=initial_jobs AND (SELECT count(*) FROM sol_action.intents)=initial_intents AND (SELECT count(*) FROM sol_action.outcomes)=initial_outcomes AND (SELECT count(*) FROM sol_action_bridge.releases)=initial_releases AND (SELECT count(*) FROM sol_creation_guard.admissions)=initial_admissions),false)));
 results:=results||jsonb_build_array(jsonb_build_object('name','all_predecessor_runtime_hashes_unchanged','pass',coalesce((sol_action.runtime_hash()=corehash AND sol_action_bridge.runtime_hash()=bridgehash AND sol_creation_guard.runtime_hash()=guardhash),false)));
 PERFORM set_config('sol_creation_guard.test_results',jsonb_build_object('scope','SYNTHETIC_DML_ROLLBACK_NOT_HTTP','tests',results,'count',jsonb_array_length(results),'failed',(SELECT count(*) FROM jsonb_array_elements(results) a WHERE a->'pass' IS DISTINCT FROM 'true'::jsonb))::text,false); END $tests$;
SELECT current_setting('sol_creation_guard.test_results')::jsonb AS test_results;
